import re

def solve(env, goal):
    def obs():
        return env.observation.lower()

    def parse_goal():
        g = goal.lower()
        m = re.search(r"put (?:an? )?(?:cool )?(\w+) (?:in|on) (?:an? )?(\w+)", g)
        if m:
            return m.group(1), m.group(2)
        m = re.search(r"(?:cool|heat|clean) (?:an? )?(\w+) (?:with|in|on) (?:an? )?(\w+)", g)
        if m:
            return m.group(1), m.group(2)
        words = re.findall(r"[a-z]+", g)
        obj_type = None
        rec_type = None
        for i, w in enumerate(words):
            if w in ("a", "an", "the", "cool", "clean", "heat", "put"):
                continue
            if obj_type is None:
                obj_type = w
            else:
                rec_type = w
                break
        return obj_type, rec_type

    obj_type, rec_type = parse_goal()
    if obj_type is None:
        obj_type = "object"
    if rec_type is None:
        rec_type = "receptacle"

    # normalize plurals
    def singular(t):
        if t.endswith("ies"):
            return t[:-3] + "y"
        if t.endswith("es") and not t.endswith("ses"):
            return t[:-2]
        if t.endswith("s") and not t.endswith("ss"):
            return t[:-1]
        return t

    obj_type = singular(obj_type)
    rec_type = singular(rec_type)

    def norm(text):
        return text.lower()

    def find_objects(text, target):
        """Return list of (name, container) for objects matching target."""
        res = []
        # patterns like "a apple 1" / "apple 1"
        for m in re.finditer(r"([a-z]+(?:\s+[a-z]+)*\s+\d+)", text):
            name = m.group(1)
            base = re.sub(r"\s*\d+$", "", name).strip()
            if base == target or base.replace(" ", "") == target:
                res.append(name)
        return res

    def current_room_receptacles():
        text = obs()
        # first observation: list receptacles
        return re.findall(r"([a-z]+(?:\s+[a-z]+)*\s+\d+)", text)

    # We will explore receptacles to find the object.
    location = None
    # track visited receptacles
    visited = set()
    inventory_has = False

    def go(cmd):
        env.step(cmd)
        return obs()

    def get_admissible():
        try:
            return env.admissible()
        except Exception:
            return []

    # Check starting observation: if object visible, take it.
    def try_take_from_current(target):
        text = obs()
        objs = find_objects(text, target)
        for name in objs:
            # need container: find "at X" or "on X"
            m = re.search(r"(?:at|on|in) ([a-z]+(?:\s+[a-z]+)*\s+\d+)", text)
            if m:
                container = m.group(1)
                env.step("take %s from %s" % (name, container))
                return True
            # fallback: try take from any receptacle token in text
            for c in re.findall(r"([a-z]+(?:\s+[a-z]+)*\s+\d+)", text):
                if c != name:
                    env.step("take %s from %s" % (name, c))
                    if "pick up" in obs() or "you pick" in obs():
                        return True
        return False

    # First, if object already visible in current room, take it.
    if try_take_from_current(obj_type):
        inventory_has = True

    if not inventory_has:
        # explore all receptacles in room
        text = obs()
        candidates = []
        for m in re.finditer(r"([a-z]+(?:\s+[a-z]+)*\s+\d+)", text):
            c = m.group(1)
            if c not in candidates:
                candidates.append(c)
        # also handle "go to X" listing
        for c in candidates:
            if c in visited:
                continue
            visited.add(c)
            # open if closed
            resp = go("go to %s" % c)
            # open if needed
            if "closed" in resp:
                go("open %s" % c)
            if try_take_from_current(obj_type):
                inventory_has = True
                break

    if not inventory_has:
        # broader exploration: use admissible commands
        for _ in range(20):
            if inventory_has:
                break
            adm = get_admissible()
            moved = False
            for cmd in adm:
                if cmd.startswith("go to ") and cmd[6:] not in visited:
                    c = cmd[6:]
                    visited.add(c)
                    resp = go(cmd)
                    if "closed" in resp:
                        go("open %s" % c)
                    if try_take_from_current(obj_type):
                        inventory_has = True
                        break
                    moved = True
            if not moved:
                break

    # Now cool the object with fridge
    if inventory_has:
        # find fridge
        fridge = None
        text = obs()
        for m in re.finditer(r"fridge\s+\d+", text):
            fridge = m.group(0)
            break
        if fridge is None:
            adm = get_admissible()
            for cmd in adm:
                if "fridge" in cmd:
                    fridge = re.search(r"fridge\s+\d+", cmd)
                    if fridge:
                        fridge = fridge.group(0)
                        break
        if fridge:
            go("go to %s" % fridge)
            # open if closed
            if "closed" in obs():
                go("open %s" % fridge)
            obj_name = None
            # find in inventory
            inv = obs()
            for m in re.finditer(r"([a-z]+(?:\s+[a-z]+)*\s+\d+)", inv):
                name = m.group(1)
                base = re.sub(r"\s*\d+$", "", name).strip()
                if base == obj_type:
                    obj_name = name
                    break
            if obj_name is None:
                # try any admissible cool command
                for cmd in get_admissible():
                    if cmd.startswith("cool "):
                        obj_name = cmd.split()[1]
                        break
            if obj_name:
                go("cool %s with %s" % (obj_name, fridge))

        # Now move to target receptacle
        target = None
        # find target receptacle in current room listing
        text = obs()
        for m in re.finditer(r"([a-z]+(?:\s+[a-z]+)*\s+\d+)", text):
            c = m.group(1)
            base = re.sub(r"\s*\d+$", "", c).strip()
            if base == rec_type:
                target = c
                break
        if target is None:
            # go to it directly
            target = rec_type + " 1"
        go("go to %s" % target)
        if "closed" in obs():
            go("open %s" % target)
        # find object in inventory
        obj_name = None
        inv = obs()
        for m in re.finditer(r"([a-z]+(?:\s+[a-z]+)*\s+\d+)", inv):
            name = m.group(1)
            base = re.sub(r"\s*\d+$", "", name).strip()
            if base == obj_type:
                obj_name = name
                break
        if obj_name is None:
            for cmd in get_admissible():
                if cmd.startswith("move "):
                    obj_name = cmd.split()[1]
                    break
        if obj_name:
            go("move %s to %s" % (obj_name, target))
